{
  "root_causes": [
    {
      "service": "ts-route-plan-service",
      "fault_kind": "application_method_slow",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT span_name, count(*) n, min(duration)/1e6 min_ms, approx_quantile(duration,0.5)/1e6 med_ms, max(duration)/1e6 max_ms FROM abnormal_traces WHERE service_name='ts-route-plan-service' AND span_name LIKE '%Route%' GROUP BY 1 ORDER BY 1",
          "claim": "getCheapestRoutes and getQuickestRoutes take a near-constant ~1856 ms, while getMinStopStations stays at ~20 ms."
        },
        {
          "kind": "trace",
          "sql": "SELECT c.service_name AS child_svc, c.span_name, p.service_name AS parent_svc, count(*) n, approx_quantile(c.duration,0.95)/1e6 p95_ms FROM abnormal_traces c JOIN abnormal_traces p ON c.parent_span_id = p.span_id AND c.trace_id=p.trace_id WHERE p.span_name IN ('RoutePlanController.getQuickestRoutes','RoutePlanController.getCheapestRoutes') GROUP BY ALL ORDER BY n DESC",
          "claim": "Inside the slow controller methods, child spans to travel, travel2 and route services stay around 20 ms, so the time is spent inside route-plan itself."
        },
        {
          "kind": "metric",
          "sql": "SELECT service_name, count(DISTINCT attr_k8s_pod_name) pods, min(value) min_v, max(value) max_v, count(*) n FROM abnormal_metrics_sum WHERE metric='k8s.pod.uptime' AND service_name='ts-route-plan-service' GROUP BY 1",
          "claim": "Route-plan has a single pod with continuous uptime, so there was no restart; the slowdown is in-process."
        }
      ]
    }
  ],
  "propagation": [
    {
      "from": "ts-route-plan-service",
      "to": "ts-travel-plan-service",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT p.service_name AS caller, p.span_name AS caller_span, c.service_name AS callee, c.span_name AS callee_span, count(*) n, approx_quantile(c.duration,0.5)/1e6 callee_med_ms, approx_quantile(p.duration,0.5)/1e6 caller_med_ms FROM abnormal_traces c JOIN abnormal_traces p ON c.parent_span_id=p.span_id AND c.trace_id=p.trace_id WHERE c.span_name IN ('POST /api/v1/routeplanservice/routePlan/cheapestRoute','POST /api/v1/routeplanservice/routePlan/quickestRoute') GROUP BY ALL ORDER BY n DESC",
          "claim": "Travel-plan's calls to route-plan's cheapestRoute and quickestRoute take about 1858 ms, matching the route-plan delay."
        }
      ]
    },
    {
      "from": "ts-travel-plan-service",
      "to": "ts-ui-dashboard",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT p.service_name AS caller, p.span_name AS caller_span, c.service_name AS callee, c.span_name AS callee_span, count(*) n, approx_quantile(c.duration,0.5)/1e6 callee_med_ms, approx_quantile(p.duration,0.5)/1e6 caller_med_ms FROM abnormal_traces c JOIN abnormal_traces p ON c.parent_span_id=p.span_id AND c.trace_id=p.trace_id WHERE c.span_name IN ('POST /api/v1/travelplanservice/travelPlan/cheapest','POST /api/v1/travelplanservice/travelPlan/quickest') GROUP BY ALL ORDER BY n DESC",
          "claim": "Dashboard's travelPlan cheapest and quickest calls take about 1862 ms, matching travel-plan's delayed calls."
        }
      ]
    }
  ]
}
